<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$cot=srnu_obtener_cotizacion($id);if(!$cot){http_response_code(404);exit('Cotización no encontrada');}
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['guardar']))$pdo->prepare('INSERT INTO costos_reales(cotizacion_id,fecha,categoria,concepto,monto,responsable,notas) VALUES(?,?,?,?,?,?,?)')->execute([$id,epost('fecha',date('Y-m-d')),epost('categoria','Material'),epost('concepto'),efloat('monto'),epost('responsable'),epost('notas')]);if(isset($_POST['eliminar']))$pdo->prepare('DELETE FROM costos_reales WHERE id=? AND cotizacion_id=?')->execute([(int)$_POST['row_id'],$id]);ego('costos.php?id='.$id);}
$s=$pdo->prepare('SELECT * FROM costos_reales WHERE cotizacion_id=? ORDER BY fecha DESC,id DESC');$s->execute([$id]);$rows=$s->fetchAll();$real=array_sum(array_map(fn($r)=>(float)$r['monto'],$rows));$estim=0;foreach($cot['items'] as $it)$estim+=(float)$it['costo_interno']*(float)$it['cantidad'];$venta=(float)$cot['subtotal'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Costos reales · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('finanzas');?><main class="w"><div class="srnu-page-heading"><div><h1>Presupuesto vs costo real</h1><p><?=eh($cot['folio'])?> · <?=eh($cot['cliente'])?> · <?=eh($cot['vehiculo'])?></p></div><a class="btn light" href="cotizaciones.php">← Cotizaciones</a></div><div class="kpi-grid"><div class="kpi"><small>Venta antes de IVA</small><strong><?=emoney($venta)?></strong></div><div class="kpi"><small>Costo presupuestado</small><strong><?=emoney($estim)?></strong></div><div class="kpi"><small>Costo real registrado</small><strong><?=emoney($real)?></strong></div><div class="kpi"><small>Utilidad real simple</small><strong><?=emoney($venta-$real)?></strong></div></div><section class="panel" style="padding:18px;margin-top:16px"><form method="post" class="erp-form cols-4"><input type="hidden" name="id" value="<?=$id?>"><input type="date" name="fecha" value="<?=date('Y-m-d')?>"><select name="categoria"><option>Material</option><option>Refacción</option><option>Envío</option><option>Mano de obra externa</option><option>Herramienta consumible</option><option>Otro</option></select><input name="concepto" required placeholder="Concepto"><input type="number" step="0.01" min="0" name="monto" required placeholder="Monto"><select name="responsable"><option value="">General</option><option>Sergio</option><option>Ricardo</option><option>Tomás</option></select><input class="full" name="notas" placeholder="Notas"><button class="btn blue" name="guardar" value="1">Agregar costo real</button></form></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Fecha</th><th>Categoría</th><th>Concepto</th><th>Responsable</th><th>Monto</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=edate($r['fecha'])?></td><td><?=eh($r['categoria'])?></td><td><?=eh($r['concepto'])?><div class="muted"><?=eh($r['notas'])?></div></td><td><?=eh($r['responsable'])?></td><td><?=emoney($r['monto'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="row_id" value="<?=$r['id']?>"><button class="btn danger" name="eliminar" value="1">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
